const r = await tools.exec_command({cmd:"python - <<'PY'
from pathlib import Path
import re, math
p=Path('run/logs/seeds_15163650.out')
t=re.sub(r'\x1b\[[0-9;]*m','',p.read_text(errors='replace'))
lines=t.splitlines()
# parse nearest step and table rows into dict
steps=[]; cur=None
for i,l in enumerate(lines):
 m=re.search(r'Epoch (\d+)/3 Step (\d+)/29 Train step (\d+)/87 done',l)
 if m:
  cur={'epoch':int(m.group(1)),'step':int(m.group(2)),'global':int(m.group(3)),'line':i+1}
  steps.append(cur); continue
 if cur and l.startswith('│'):
  # split cells; each triplet key,val,key,val...
  cells=[x.strip() for x in l.strip('│').split('│')]
  for j in range(0,len(cells)-1,2):
   k,v=cells[j],cells[j+1]
   if not k: continue
   try: cur[k]=float(v.replace(',',''))
   except: pass
print('steps',len(steps))
keys=['rollout/reward','eval-rollout/reward','ppo_actor/task_reward/avg','ppo_actor/final_reward/avg','ppo_actor/correct_n_seqs','ppo_actor/incorrect_n_seqs','ppo_actor/seq_len/avg','ppo_actor/seq_len/max','ppo_actor/no_eos_ratios/avg','ppo_actor/update/rs_filtered_fraction','ppo_actor/update/masked_token_ratio','ppo_actor/update/grad_norm','ppo_actor/update/approx_kl/avg','ppo_actor/update/behave_approx_kl/avg','ppo_actor/update/logp_abs_diff/avg','ppo_actor/update/n_valid_tokens_in_loss','ppo_actor/update/n_valid_tokens','timeperf/rollout','timeperf/train_step','timeperf/update_weights']
print('\t'.join(['epoch','step','global']+keys))
for s in steps:
 print('\t'.join([str(s.get(x,'')) for x in ['epoch','step','global']]+[f"{s.get(k,float('nan')):.6g}" if k in s else '' for k in keys]))
# all eval reward lines
print('\nEVAL REWARD OCCURRENCES')
for i,l in enumerate(lines):
 if 'eval-rollout/reward' in l:
  print(i+1,l.strip())
PY","workdir":"/workspace","yield_time_ms":10000,"max_output_tokens":40000}); text(r.output);

