terms=['update_weights_from_distributed','areal_update_weights','Weight update','weight update','initialized','Loading weights','broadcast','abort all','Server disconnected','HTTP request','failed with','Exception']
for fn in ['actor.log','rollout.log','proxy-rollout.log','main.log']:
