const r = await tools.exec_command({cmd:"python - <<'PY'
from pathlib import Path
import re
p=Path('run/experiments/logs/user/kt-seeds/icepop_w067-s2/main.log')
ls=p.read_text(errors='ignore').replace('\x1b','').splitlines()
starts=[]
for i,l in enumerate(ls):
 m=re.search(r'StatsLogger INFO: Epoch (\d+)/(\d+) Step (\d+)/(\d+) Train step (\d+)/(\d+) done',l)
 if m: starts.append((i,tuple(map(int,m.groups()))))
keys=['sample_staleness_proximal_avg','sample_staleness_theta_avg','sample_staleness_proximal_min','sample_staleness_proximal_max','sample_staleness_theta_min','sample_staleness_theta_max','v_proximal','v_theta','n_valid_generated_tokens','n_valid_tokens','version_stats']
for n,(i,m) in enumerate(starts):
 j=starts[n+1][0] if n+1<len(starts) else len(ls)
 vals={}
 for l in ls[i:j]:
  if '│' not in l: continue
  parts=l.split('│')
  for q in range(1,len(parts)-1,2):
   k=parts[q].strip();v=parts[q+1].strip()
   if k in keys:
    try: vals[k]=float(v)
    except:vals[k]=v
 print(m[4], vals)
PY",workdir:"/workspace",yield_time_ms:10000,max_output_tokens:30000});
text(r.output);

