from pathlib import Path
import re
p=Path('run/experiments/logs/user/kt-seeds/icepop_w067-s2/main.log')
lines=p.read_text(errors='replace').splitlines()
starts=[]
for i,l in enumerate(lines):
 m=re.search(r'StatsLogger INFO: Epoch (\d+)/(\d+) Step (\d+)/(\d+) Train step (\d+)/(\d+) done',l)
 if m: starts.append((i,tuple(map(int,m.groups()))))
print('tables',len(starts))
keys=['ppo_actor/task_reward/avg','ppo_actor/final_reward/avg','ppo_actor/correct_n_seqs','ppo_actor/incorrect_n_seqs','ppo_actor/seq_len/avg','ppo_actor/no_eos_ratios/avg','ppo_actor/rs_filtered_fraction','ppo_actor/update/behave_filtered_ratio/avg','ppo_actor/update/behave_approx_kl/avg','ppo_actor/update/compute_logp/kl_div_direct/avg','ppo_actor/update/approx_kl/avg','ppo_actor/update/grad_norm','ppo_actor/update/actor_loss/avg','ppo_actor/n_valid_tokens','ppo_actor/n_tokens','ppo_actor/n_valid_generated_tokens','eval-rollout/reward','rollout/reward','timeperf/train_step','timeperf/rollout','timeperf/recompute_logp','timeperf/compute_advantage','timeperf/update_weights']
def val(block,key):
 # row has key and one value likely │ key │ value │ ...; preserve scientific
 for l in block:
  if f'│ {key} ' in l:
   parts=l.split('│')
   for j,x in enumerate(parts):
    if key in x:
     # value next part
     if j+1<len(parts): return parts[j+1].strip()
 return ''
for idx,(i,meta) in enumerate(starts):
 block=lines[i:i+90]
 vals={k:val(block,k) for k in keys}
 print(*meta, *(vals[k] for k in keys))
PY",workdir:"/workspace",yield_time_ms:10000,max_output_tokens:40000}); text(r.output);

