import re
raw=open('run/logs/seeds_15163650.out').read(); lines=[re.sub(r'\x1b\[[0-9;]*m','',x) for x in raw.splitlines()]
# metrics blocks begin around each step and run until StatsLogger line next
steps=[]
for i,l in enumerate(lines):
 m=re.search(r'StatsLogger INFO: Epoch (\d+)/(\d+) Step (\d+)/(\d+) Train step (\d+)/(\d+) done',l)
 if m:
  vals={'epoch':int(m.group(1)),'step':int(m.group(3)),'global':int(m.group(5))}
  for z in lines[i+1:i+90]:
   # row has key between │
   for key in ['eval-rollout/reward','rollout/reward','ppo_actor/task_reward/avg','ppo_actor/no_eos_ratios/avg','ppo_actor/update/behave_filtered_ratio/avg','ppo_actor/update/rs_filtered_fraction','ppo_actor/seq_len/avg','ppo_actor/update/logp_abs_diff/avg','ppo_actor/update/approx_kl/avg','timeperf/rollout','timeperf/train_step','timeperf/eval','ppo_actor/update/masked_token_ratio','ppo_actor/update/n_masked_tokens','ppo_actor/update/n_valid_tokens_in_loss']:
    if key in z:
      parts=z.split('│')
      for j,p in enumerate(parts):
       if key in p and j+1<len(parts):
        x=parts[j+1].strip().split()[0]
        vals[key]=x
  steps.append(vals)
for s in steps:
 if s['step'] in [1,10,20,29]: print(s)
