from pathlib import Path
import re
s=Path('/workspace/run/experiments/logs/user/kt-seeds/icepop_w067-s2/main.log').read_text(errors='replace')
s=re.sub(r'\x1b\[[0-9;]*m','',s)
lines=s.splitlines()
# blocks beginning StatsLogger INFO: Stats
for i,l in enumerate(lines):
 if 'StatsLogger INFO: Epoch' in l:
  print('\nSTEP', re.search(r'Epoch (\d+/\d+) Step (\d+/\d+) Train step (\d+/\d+)',l).groups())
  # next 80 lines until box end
  block='\n'.join(lines[i:i+75])
  keys=['task_reward/avg','rollout/reward','eval-rollout/reward','rs_filtered_fraction','masked_token_ratio','no_eos_ratios/avg','seq_len/avg','seq_len/max','correct_n_seqs','correct_seq_len/avg','update/actor_loss/avg','update/approx_kl/avg','update/behave_approx_kl/avg','update/grad_norm','timeperf/rollout','timeperf/train_step','timeperf/update_weights','timeperf/eval','update/version_stats/sample_staleness_theta_avg','update/version_stats/sample_staleness_proximal_avg','update/n_valid_tokens_in_loss']
  vals=[]
  for k in keys:
   # allow line with key and value second pipe
   m=re.search(r'│\s*'+re.escape('ppo_actor/'+k)+r'\s*│\s*([^│]+)',block)
   if not m: m=re.search(r'│\s*'+re.escape('timeperf/'+k)+r'\s*│\s*([^│]+)',block)
   if not m: m=re.search(r'│\s*'+re.escape('eval-rollout/'+k)+r'\s*│\s*([^│]+)',block)
   if m: vals.append(k+'='+m.group(1).strip())
  print(' '.join(vals))
