        for x in lines[i:i+100]:
            y=re.sub(r'\x1b\[[0-9;]*m','',x)
            if any(k in y for k in ['task_reward/avg','eval-rollout/reward','correct_n_seqs','incorrect_n_seqs','seq_len/avg','masked_token_ratio','rs_filtered_fraction','behave_filtered_ratio/avg','actor_loss/avg','grad_norm','entropy/avg','no_eos_ratios/avg','timeperf/rollout','timeperf/train_step','timeperf/eval']):
