keys=['rollout/reward','eval-rollout/reward','ppo_actor/task_reward/avg','ppo_actor/no_eos_ratios/avg','ppo_actor/seq_len/avg','ppo_actor/seq_len/max','ppo_actor/correct_n_seqs','ppo_actor/incorrect_n_seqs','ppo_actor/update/actor_loss/avg','ppo_actor/update/approx_kl/avg','ppo_actor/update/behave_approx_kl/avg','ppo_actor/update/logp_abs_diff/avg','ppo_actor/update/behave_filtered_ratio/avg','ppo_actor/update/masked_token_ratio','ppo_actor/update/n_valid_tokens_in_loss','ppo_actor/update/grad_norm','timeperf/rollout','timeperf/train_step','timeperf/recompute_logp','timeperf/update_weights','ppo_actor/update/version_stats/sample_staleness_theta_avg','ppo_actor/update/version_stats/sample_staleness_proximal_avg']
# line table parse: key │ value; each row contains 4 pairs
