for k in keys:
 vals=[d[k] for _,d in allrows if k in d]
 if vals: print(k, 'n',len(vals),'first',vals[:3],'last',vals[-3:],'min',min(vals),'max',max(vals),'mean',sum(vals)/len(vals))
