import re
from pathlib import Path
s=Path('run/experiments/logs/user/kt-seeds/icepop_w067-s2/main.log').read_text(errors='replace')
lines=s.splitlines()
steps=[]
for i,l in enumerate(lines):
 m=re.search(r'Epoch (\d+)/3 Step (\d+)/29 Train step (\d+)/87 done',l)
 if m:
  d={'epoch':int(m.group(1)),'estep':int(m.group(2)),'step':int(m.group(3))}
  # table until next marker or 100 lines
  for x in lines[i+1:i+80]:
   mm=re.search(r'│\s*([^│]+?)\s*│\s*([^│]+?)\s*│',x)
   if mm:
    k=mm.group(1).strip(); v=mm.group(2).strip()
    if k in ['rollout/reward','eval-rollout/reward','ppo_actor/task_reward/avg','ppo_actor/correct_n_seqs','ppo_actor/incorrect_n_seqs','ppo_actor/seq_len/avg','ppo_actor/seq_len/max','ppo_actor/no_eos_ratios/avg','ppo_actor/no_eos_ratios/max','ppo_actor/update/rs_filtered_fraction','ppo_actor/update/compute_logp/kl_div_direct/avg','ppo_actor/update/compute_logp/kl_div_direct/max','ppo_actor/update/behave_approx_kl/avg','ppo_actor/update/grad_norm','timeperf/rollout','timeperf/train_step','timeperf/update_weights','ppo_actor/advantages/avg','ppo_actor/update/n_valid_tokens','ppo_actor/n_valid_tokens','ppo_actor/n_tokens']:
     try: d[k]=float(v.replace('e+','e+').replace('e-','e-'))
     except: d[k]=v
