 m=re.search(r'Epoch (\d+)/(\d+) Step (\d+)/(\d+) Train step (\d+)/(\d+) done',l)
 if m:
  if cur: steps.append(cur)
  cur={'epoch':int(m.group(1)),'step':int(m.group(3)),'global':int(m.group(5))}
 if cur:
  # table line with key/value possibly two columns; regex all segments between │
  if '│' in l:
   seg=[s.strip() for s in l.split('│')]
   # parse pairs as key, val alternating ignoring first/last empty
   for i in range(1,len(seg)-1,2):
    if i+1<len(seg):
     k=seg[i]; v=seg[i+1]
     if k:
      cur[k]=v
 if len(steps)>=87: break
if cur: steps.append(cur)
print('n steps',len(steps))
for x in steps:
 keys=['ppo_actor/task_reward/avg','eval-rollout/reward','ppo_actor/correct_n_seqs','ppo_actor/n_seqs','ppo_actor/seq_len/avg','ppo_actor/seq_len/max','ppo_actor/no_eos_ratios/avg','ppo_actor/update/rs_filtered_fraction','ppo_actor/update/behave_filtered_ratio/avg','ppo_actor/update/logp_abs_diff/avg','ppo_actor/update/behave_approx_kl/avg','ppo_actor/update/n_valid_tokens_in_loss','ppo_actor/update/version_stats/sample_staleness_theta_avg','ppo_actor/update/version_stats/v_theta','timeperf/rollout','timeperf/train_step','timeperf/eval']
