from pathlib import Path
import re, collections
for fn in ['actor.log','main.log','rollout.log','proxy-rollout.log','eval-rollout.log']:
 p=Path('run/experiments/logs/user/kt-seeds/icepop_w067-s2')/fn
 lines=[]
 for i,line in enumerate(p.read_text(errors='replace').splitlines(),1):
  line=re.sub(r'\x1b\[[0-9;]*m','',line)
  # remove timestamp prefix to focus text
  if fn=='actor.log':
   if any(k in line.lower() for k in ['step','epoch','reward','loss','kl','ratio','mask','entropy','adv','policy','grad','throughput','token','trunc','finished','stats','train']): lines.append((i,line))
  elif fn=='main.log':
   if any(k in line.lower() for k in ['evaluation results','evaluate','eval stats','epoch','step','training finished','training completed','reward','loss','rollout stats','trunc','finished']): lines.append((i,line))
  elif fn=='rollout.log':
   if any(k in line.lower() for k in ['stats','reward','trunc','length','error','exception','timeout','warning','finished','submitted']): lines.append((i,line))
