from pathlib import Path
import re
p=Path('run/experiments/logs/user/kt-seeds/icepop_w067-s2/main.log')
t=re.sub(r'\x1b\[[0-9;]*m','',p.read_text(errors='replace'))
ls=t.splitlines()
# identify lines with Epoch and next 70 lines table; parse all key-value rows with │ key │ val │ key │ val...
keys=['ppo_actor/task_reward/avg','rollout/reward','eval-rollout/reward','ppo_actor/update/rs_filtered_fraction','ppo_actor/update/behave_filtered_ratio/avg','ppo_actor/update/behave_approx_kl/avg','ppo_actor/update/logp_diff/avg','ppo_actor/no_eos_ratios/avg','ppo_actor/seq_len/avg','ppo_actor/correct_n_seqs','ppo_actor/incorrect_n_seqs','timeperf/train_step','ppo_actor/update/grad_norm','ppo_actor/update/actor_loss/avg','ppo_actor/update/new_logp/avg','ppo_actor/update/old_logp/avg','ppo_actor/update/compute_logp/kl_div_direct/avg','ppo_actor/update/masked_token_ratio']
records=[]
for i,l in enumerate(ls):
 m=re.search(r'StatsLogger INFO: Epoch (\d+)/3 Step (\d+)/29 Train step (\d+)/87 done',l)
 if not m: continue
 rec={'epoch':int(m.group(1)),'step':int(m.group(3)),'line':i+1}
 for x in ls[i+1:i+75]:
  # split key/value pairs robustly
  parts=x.split('│')
  if len(parts)<5: continue
  for j in range(1,len(parts)-1,2):
   k=parts[j].strip(); v=parts[j+1].strip()
   if k in keys:
    try: rec[k]=float(v)
    except: pass
 records.append(rec)
for r in records:
 if r['step']==1 or r['step']%5==0 or r['step'] in [28,29,30,58,59,87]:
  print(' '.join(f'{k.split("/")[-1]}={r[k]:.4g}' for k in ['epoch','step'] if k in r), ' '.join(f'{k.split("/")[-1]}={r.get(k,float("nan")):.4g}' for k in keys if k in r))
print('records',len(records))
# aggregate epochs from records
for e in [1,2,3]:
 rr=[r for r in records if r['epoch']==e]
 print('epoch',e,'n',len(rr))
 for k in keys:
  vals=[r[k] for r in rr if k in r]
  if vals: print(k,'first',vals[0],'last',vals[-1],'mean',sum(vals)/len(vals),'min',min(vals),'max',max(vals))
PY",workdir:"/workspace",yield_time_ms:10000,max_output_tokens:30000}); text(r.output);

