import re, pathlib
s=pathlib.Path('/tmp/main.log').read_text()
lines=s.splitlines()
# extract step headers and nearby metric lines; metrics table each line keys rows. Build simple collect by blocks after Stats table.
steps=[]
for i,l in enumerate(lines):
 m=re.search(r'Epoch (\d+)/3 Step (\d+)/29 Train step (\d+)/87 done', l)
 if m:
  steps.append((i,int(m.group(1)),int(m.group(2)),int(m.group(3))))
print('steps',len(steps))
keys=['rollout/reward','eval-rollout/reward','task_reward/avg','correct_n_seqs','no_eos_ratios/avg','seq_len/avg','masked_token_ratio','rs_filtered_fraction','behave_approx_kl/avg','grad_norm','actor_loss/avg','approx_kl/avg','entropy/avg','timeperf/train_step','timeperf/eval']
for j,(i,e,st,t) in enumerate(steps):
 end=steps[j+1][0] if j+1<len(steps) else len(lines)
 block='\n'.join(lines[i:end])
 vals={}
 for key in keys:
  # lines have unicode box; key spaces maybe exact
  pat=re.compile(re.escape(key)+r'\s*[│|]?\s*([+\-0-9.eE]+)')
  ms=pat.findall(block)
  if ms: vals[key]=ms[-1]
 print(e,st,t, ' '.join(f'{k}={vals.get(k,"?")}' for k in keys))
PY",workdir:"/workspace",yield_time_ms:10000,max_output_tokens:30000}); text(r.output);

