from pathlib import Path
import re, math, json
ansi=re.compile(r'\x1b\[[0-9;?]*[ -/]*[@-~]')
fn='run/logs/seeds_15163650.out'
lines=ansi.sub('',Path(fn).read_text(errors='replace')).splitlines()
# parse all table rows with 4 cells; metric values numeric
