 if not m: continue
 for j in range(0,8,2):
  k=m.group(j+1).strip(); v=m.group(j+2).strip()
  if k:
   try: val=float(v.replace(',',''))
   except: val=v
   allm.append((i,k,val))
# group to latest preceding Train step line
steps=[]
for i,l in enumerate(lines):
 m=re.search(r'Train step (\d+)/87 done',l)
