 end=steps[idx+1][0] if idx+1<len(steps) else len(lines)
 d={k:v for ii,k,v in allm if line < ii < end}
 metrics[step]=d
keys=['ppo_actor/task_reward/avg','ppo_actor/final_reward/avg','ppo_actor/final_reward/max','ppo_actor/correct_n_seqs','ppo_actor/incorrect_n_seqs','ppo_actor/correct_seq_len/avg','ppo_actor/incorrect_seq_len/avg','ppo_actor/no_eos_ratios/avg','ppo_actor/update/behave_filtered_ratio/avg','ppo_actor/update/rs_filtered_fraction','ppo_actor/update/importance_weight/avg','ppo_actor/update/behave_approx_kl/avg','ppo_actor/update/compute_logp/kl_div_direct/avg','ppo_actor/update/compute_logp/kl_div_taylor/avg','ppo_actor/update/grad_norm','ppo_actor/update/entropy/avg','ppo_actor/update/actor_loss/avg','ppo_actor/update/logp_diff/avg','ppo_actor/update/masked_token_ratio','rollout/reward','eval-rollout/reward','timeperf/rollout','timeperf/update_weights','ppo_actor/n_tokens','ppo_actor/n_valid_tokens']
print('step,'+','.join(keys))
for s in range(1,88):
 d=metrics.get(s,{})
 print(s,','.join(str(d.get(k,'')) for k in keys))
