from pathlib import Path
import re
s=Path('/tmp/main.clean').read_text()
lines=s.splitlines()
# capture tables by finding each line containing StatsLogger epoch, then previous/next? Print metrics around each epoch marker and table values via regex line.
keys=['rollout/reward','eval-rollout/reward','ppo_actor/task_reward/avg','ppo_actor/seq_len/avg','ppo_actor/no_eos_ratios/avg','ppo_actor/update/behave_filtered_ratio/avg','ppo_actor/update/rs_filtered_fraction','ppo_actor/update/logp_abs_diff/avg','ppo_actor/update/behave_approx_kl/avg','timeperf/rollout','timeperf/train_step','timeperf/eval','ppo_actor/incorrect_n_seqs','ppo_actor/correct_n_seqs','ppo_actor/update/entropy/avg','ppo_actor/update/grad_norm','ppo_actor/update/update_successful']
# Each table line contains 2 cols, maybe each metric line separate. parse line segments with boxes and key
vals=[]
step=None
for i,l in enumerate(lines):
 m=re.search(r'Epoch (\d+)/3 Step (\d+)/29 Train step (\d+)/87 done',l)
 if m: step=tuple(map(int,m.groups())); vals.append({'step':step,'line':i+1})
 if step:
  # find all key and number in line; if table starts etc
  for k in keys:
   if k in l:
    # after key maybe spaces │ num
    mm=re.search(re.escape(k)+r'\s+│\s+([^ │]+)',l)
    if mm: vals[-1][k]=mm.group(1)
# But table metrics precede marker, so association wrong. Better table spans from marker to next marker; marker is end. Print table start before marker maybe previous 73 lines.
print('markers',len(vals))
for x in vals:
 print(x)
