const baseline = load("repair_baseline");
const script = `from pathlib import Path
import json, re, shlex
from hydra import compose, initialize_config_dir
from omegaconf import OmegaConf

old_script = ${JSON.stringify(baseline.original_run_sh)}
env = {"W":"/workspace", "SEED":"2", "RLROOT":"/workspace/validation-output-unused",
       "MODEL_PATH":"/workspace/models/Qwen1.5-MoE-A2.7B-Chat",
       "DATA_PATH":"/workspace/data/gsm8k"}
def parse(text):
    start = text.index("python examples/math/gsm8k_rl.py")
    args = shlex.split(text[start:].replace("\\\\\\n", ""))
    def expand(s):
        return re.sub(r"\\$\\{(\\w+)\\}|\\$(\\w+)", lambda m: env[m[1] or m[2]], s)
    args = [expand(a) for a in args]
    assert args[:4] == ["python", "examples/math/gsm8k_rl.py", "--config", "examples/math/gsm8k_icepop.yaml"]
    with initialize_config_dir(config_dir="/workspace/examples/math", version_base=None):
        cfg = compose(config_name="gsm8k_icepop", overrides=args[4:])
    return OmegaConf.to_container(cfg, resolve=True)
old = parse(old_script)
new = parse(Path("/workspace/run.sh").read_text())
def flatten(v, prefix=""):
    out = {}
    if isinstance(v,dict):
        for k,x in v.items(): out.update(flatten(x, f"{prefix}.{k}" if prefix else k))
    else: out[prefix] = v
    return out
a,b=flatten(old),flatten(new)
diff = {k: [a.get(k),b.get(k)] for k in a.keys()|b.keys() if a.get(k)!=b.get(k)}
assert diff == {"actor.optimizer.lr":[3e-6,2e-6],"actor.optimizer.lr_scheduler_type":["constant","cosine"]}, diff
assert new["total_train_epochs"] == 3 and new["seed"]==2
assert new["train_dataset"]["batch_size"] == 256
assert new["actor"]["backend"] == "fsdp:d4p1t1"
assert new["rollout"]["backend"] == "sglang:d4p1t1"
assert new["evaluator"]["freq_epochs"] == 1
assert new["actor"]["weight_update_mode"] == "xccl"
assert new["cluster"]["fileroot"] == env["RLROOT"]+"/experiments"
assert new["train_dataset"]["path"] == new["valid_dataset"]["path"] == env["DATA_PATH"]
assert new["actor"]["path"] == new["tokenizer_path"] == env["MODEL_PATH"]
assert new["actor"]["rejection_sampling"] == {"level":"token","action":"mask","metric":"ratio","lower":0.67,"upper":1.5}
print("Hydra composition passed. Only effective changes:",json.dumps(diff,sort_keys=True))
print("Budget, seed, allocation, evaluation frequency, data/model paths, weight sync, rejection bounds, and output routing passed.")
print("No launcher was executed and no evaluation/output files were written.")
`;
